for spec in specs(e2e.get('suites',[])):
    tests=spec.get('tests',[]);okay=bool(tests) and all(x.get('status')=='expected' for x in tests)
    add(spec['title'],'passed' if okay else 'failed',f'evidence/{e2e_file}',cat='Functionality',actual='Chromium production-build UI assertions passed' if okay else 'See browser result')
