counts=collections.Counter(x['status'] for x in cases)
scores={}
for cat in ['Functionality','Security','Database integrity','Financial accuracy','Inventory','UI/UX','Performance','Documentation']:
    rows=[x for x in cases if x['category']==cat];scores[cat]={'passed':sum(x['status']=='passed' for x in rows),'applicable':len(rows),'score':round(100*sum(x['status']=='passed' for x in rows)/len(rows),1) if rows else 0}
overall=round(sum(x['score'] for x in scores.values())/len(scores),1)
(E/'audit-summary.json').write_text(json.dumps({'cases':len(cases),'counts':counts,'scores':scores,'readinessEvidenceScore':overall,'verdict':'NO-GO'},indent=2),encoding='utf-8')
