features=[]
test_sources={str(p.relative_to(ROOT)):p.read_text(encoding='utf-8') for p in (ROOT/'tests').rglob('*.test.ts')}
for p in sorted((ROOT/'src/modules').rglob('*.ts')):
    if p.name in ['actions.ts','serialize.ts']:continue
    for name in re.findall(r'export\s+(?:async\s+)?function\s+(\w+)\s*\(',p.read_text(encoding='utf-8')):
        refs=[path for path,text in test_sources.items() if re.search(r'\b'+re.escape(name)+r'\s*\(',text)]
        features.append({'module':p.relative_to(ROOT/'src/modules').parts[0],'operation':name,'source':str(p.relative_to(ROOT)).replace('\\','/'),'status':'Partially working' if refs else 'Unable to test','evidence':'; '.join(refs),'limitation':'Referenced by service tests; not full UI certification' if refs else 'Source exists; no direct test-call reference found'})
