bugs=[('B01','High','Fixed locally','Restricted attachment filenames and totals were visible through project/org document browsers. Added module permission filters before count/pagination, including supplier/client note separation.','document-visibility.test.ts'),('B02','Low','Fixed locally','Malformed upload Origin could throw before structured error handling. Invalid/missing/non-HTTP origins now return rejection.','upload-origin.test.ts'),('B03','Medium','Fixed locally','Browser fixture inherited production CA and could not bootstrap local PostgreSQL. E2E_DB_SSL_CA explicitly isolates TLS settings.','E2E bootstrap and 9 passing browser tests'),('B04','Low','Fixed locally','Browser login selected both Password and Show password. Selector now uses an exact accessible label.','9 passing browser tests'),('B05','High','Open','Dependency audit reports 8 affected packages, including 4 high entries. No automatic fix available in the audited tree.','dependencies.json'),('B06','High','Decision required','Requested supplier-bill stock rule differs from implemented GRN posting. Never silently change the stock trigger.','complete-training-workflow.test.ts'),('B07','Medium','Open','Upload sniffing accepts XLSX based on ZIP signature and extension; CSV is only a lightweight NUL check. This does not establish safe workbook/text contents or malware freedom.','src/lib/storage/sniff.ts'),('B08','Medium','Open','Project Accounts stops at 1000 projects without a pagination/truncation message; large portfolios can yield incomplete totals.','src/modules/insights/accounts.ts'),('B09','Low','Open','ESLint initially reported 10 unused-variable warnings; final check records the remaining warning count.','lint-initial.txt and lint-final.txt')]
